import React from "react";

const SummaryCards = ({ transactions }) => {
  const total = transactions.reduce((acc, t) => acc + Number(t.amount), 0);

  return (
    <div style={{
      background: "white",
      padding: "20px",
      borderRadius: "10px",
      boxShadow: "0 2px 5px rgba(0,0,0,0.1)"
    }}>
      <h3>Total Balance</h3>
      <h1>₹{total}</h1>
    </div>
  );
};

export default SummaryCards;
